CREATE FUNCTION padova.app_cents(value numeric) RETURNS bigint LANGUAGE plpgsql IMMUTABLE STRICT SET search_path='' AS $$ BEGIN IF value*100<>trunc(value*100) OR abs(value*100)>9000000000000 THEN RAISE EXCEPTION 'Money cannot be represented safely in application cents'; END IF; RETURN (value*100)::bigint; END $$;
CREATE FUNCTION padova.app_whole(value numeric) RETURNS bigint LANGUAGE plpgsql IMMUTABLE STRICT SET search_path='' AS $$ BEGIN IF value<>trunc(value) OR abs(value)>9007199254740991 THEN RAISE EXCEPTION 'Quantity must be a safe whole number'; END IF; RETURN value::bigint; END $$;
