 ELSIF TG_OP='UPDATE' THEN
 UPDATE padova."asset_acquisition_payments" SET "asset_id"=NEW."asset_id","payment_id"=NEW."payment_id","amount"=NEW."amount"::numeric/100,"command_id"=NEW."command_id" WHERE "id"=OLD."id";
 ELSE RAISE EXCEPTION 'Adapter deletion is not permitted'; END IF; RETURN NEW; END $$;
