CREATE VIEW padova.app_asset_movements WITH (security_invoker=true) AS SELECT b."id" AS "id",b."asset_id" AS "asset_id",b."app_lot_id" AS "lot_id",b."booking_id" AS "booking_id",COALESCE(b.app_quantity,CASE WHEN a.kind='points' THEN padova.app_whole(b.face_delta) ELSE padova.app_cents(b.face_delta) END) AS "quantity",padova.app_cents(b."basis_delta") AS "basis",COALESCE(b.app_kind,b.kind) AS "kind",b."effective_date" AS "effective_on",b."app_original_movement_id" AS "original_movement_id",b."app_command_id" AS "command_id" FROM padova."asset_movements" b JOIN padova.assets a ON a.id=b.asset_id;
