CREATE FUNCTION padova.app_write_asset_movements() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN
 IF TG_OP='INSERT' THEN
 INSERT INTO padova."asset_movements" ("id","asset_id","app_lot_id","booking_id","app_quantity","basis_delta","kind","effective_date","app_original_movement_id","app_command_id","app_kind","face_delta") VALUES (NEW."id",NEW."asset_id",NEW."lot_id",NEW."booking_id",NEW.quantity,NEW."basis"::numeric/100,CASE WHEN NEW.kind='sale' THEN 'sale' WHEN NEW.kind='expiration' THEN 'expiry' WHEN NEW.kind IN ('acquisition','earned_credit','voucherization','supplier_refund') THEN 'create' WHEN NEW.quantity>0 THEN 'return' ELSE 'use' END,NEW."effective_on",NEW."original_movement_id",NEW."command_id",NEW.kind,CASE WHEN (SELECT kind FROM padova.assets WHERE id=NEW.asset_id)='points' THEN NEW.quantity ELSE NEW.quantity::numeric/100 END);
 ELSIF TG_OP='UPDATE' THEN
 UPDATE padova."asset_movements" SET "asset_id"=NEW."asset_id","app_lot_id"=NEW."lot_id","booking_id"=NEW."booking_id","app_quantity"=NEW.quantity,"basis_delta"=NEW."basis"::numeric/100,"kind"=CASE WHEN NEW.kind='sale' THEN 'sale' WHEN NEW.kind='expiration' THEN 'expiry' WHEN NEW.kind IN ('acquisition','earned_credit','voucherization','supplier_refund') THEN 'create' WHEN NEW.quantity>0 THEN 'return' ELSE 'use' END,"effective_date"=NEW."effective_on","app_original_movement_id"=NEW."original_movement_id","app_command_id"=NEW."command_id","app_kind"=NEW.kind,"face_delta"=CASE WHEN (SELECT kind FROM padova.assets WHERE id=NEW.asset_id)='points' THEN NEW.quantity ELSE NEW.quantity::numeric/100 END WHERE "id"=OLD."id";
 ELSE RAISE EXCEPTION 'Adapter deletion is not permitted'; END IF; RETURN NEW; END $$;
