CREATE FUNCTION padova.app_write_bookings() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN
 IF TG_OP='INSERT' THEN
 INSERT INTO padova."bookings" ("id","app_code","customer_id","supplier_id","app_product","app_channel","summary","booked_date","travel_date","end_date","status","app_confirmation_status","app_document_status","app_itinerary","version","app_currency","created_at","kind","verification","app_managed") VALUES (NEW."id",NEW."code",NEW."customer_id",NEW."supplier_id",NEW."product",NEW."channel",NEW."summary",NEW."booked_on",NEW."travel_start",NEW."travel_end",NEW."reservation_status",NEW."confirmation_status",NEW."document_status",NEW."itinerary",NEW."revision",NEW."currency",NEW."created_at",'standard','owner_confirmed',true);
 ELSIF TG_OP='UPDATE' THEN
 IF NOT COALESCE(OLD.adapter_managed,false) THEN RAISE EXCEPTION 'Existing booking needs explicit compatibility review'; END IF; UPDATE padova."bookings" SET "app_code"=NEW."code","customer_id"=NEW."customer_id","supplier_id"=NEW."supplier_id","app_product"=NEW."product","app_channel"=NEW."channel","summary"=NEW."summary","booked_date"=NEW."booked_on","travel_date"=NEW."travel_start","end_date"=NEW."travel_end","status"=NEW."reservation_status","app_confirmation_status"=NEW."confirmation_status","app_document_status"=NEW."document_status","app_itinerary"=NEW."itinerary","version"=NEW."revision","app_currency"=NEW."currency","created_at"=NEW."created_at","kind"='standard',"verification"='owner_confirmed',"app_managed"=true WHERE "id"=OLD."id";
 ELSE RAISE EXCEPTION 'Adapter deletion is not permitted'; END IF; RETURN NEW; END $$;
CREATE TRIGGER app_write INSTEAD OF INSERT OR UPDATE ON padova.app_bookings FOR EACH ROW EXECUTE FUNCTION padova.app_write_bookings();
