 IF TG_OP='INSERT' THEN
 INSERT INTO padova."charges" ("id","booking_id","kind","amount","effective_date","app_command_id","app_kind","verification") VALUES (NEW."id",NEW."booking_id",CASE WHEN NEW.kind='sale' THEN 'fare' ELSE 'adjustment' END,NEW."amount"::numeric/100,NEW."effective_on",NEW."command_id",NEW.kind,'owner_confirmed');
 ELSIF TG_OP='UPDATE' THEN
 UPDATE padova."charges" SET "booking_id"=NEW."booking_id","kind"=CASE WHEN NEW.kind='sale' THEN 'fare' ELSE 'adjustment' END,"amount"=NEW."amount"::numeric/100,"effective_date"=NEW."effective_on","app_command_id"=NEW."command_id","app_kind"=NEW.kind,"verification"='owner_confirmed' WHERE "id"=OLD."id";
 ELSE RAISE EXCEPTION 'Adapter deletion is not permitted'; END IF; RETURN NEW; END $$;
