 IF TG_OP='INSERT' THEN
 INSERT INTO padova."commissions" ("id","booking_id","app_payer_id","app_collector_id","gross","retention","app_due_on","app_command_id","intermediary_id","stay_end") VALUES (NEW."id",NEW."booking_id",NEW."payer_id",NEW."collector_id",NEW."gross"::numeric/100,NEW."retained"::numeric/100,NEW."due_on",NEW."command_id",COALESCE(NEW.collector_id,NEW.payer_id),COALESCE((SELECT end_date FROM padova.bookings WHERE id=NEW.booking_id),NEW.due_on));
 ELSIF TG_OP='UPDATE' THEN
 UPDATE padova."commissions" SET "booking_id"=NEW."booking_id","app_payer_id"=NEW."payer_id","app_collector_id"=NEW."collector_id","gross"=NEW."gross"::numeric/100,"retention"=NEW."retained"::numeric/100,"app_due_on"=NEW."due_on","app_command_id"=NEW."command_id","intermediary_id"=COALESCE(NEW.collector_id,NEW.payer_id),"stay_end"=COALESCE((SELECT end_date FROM padova.bookings WHERE id=NEW.booking_id),NEW.due_on) WHERE "id"=OLD."id";
 ELSE RAISE EXCEPTION 'Adapter deletion is not permitted'; END IF; RETURN NEW; END $$;
