 INSERT INTO padova."referral_payments" ("id","terms_id","app_payment_id","amount","app_command_id","paid_date","reference") VALUES (NEW."id",NEW."referral_id",NEW."payment_id",NEW."amount"::numeric/100,NEW."command_id",(SELECT paid_on FROM padova.app_payments WHERE id=NEW.payment_id),COALESCE((SELECT reference FROM padova.app_payments WHERE id=NEW.payment_id),''));
 ELSIF TG_OP='UPDATE' THEN
 UPDATE padova."referral_payments" SET "terms_id"=NEW."referral_id","app_payment_id"=NEW."payment_id","amount"=NEW."amount"::numeric/100,"app_command_id"=NEW."command_id","paid_date"=(SELECT paid_on FROM padova.app_payments WHERE id=NEW.payment_id),"reference"=COALESCE((SELECT reference FROM padova.app_payments WHERE id=NEW.payment_id),'') WHERE "id"=OLD."id";
 ELSE RAISE EXCEPTION 'Adapter deletion is not permitted'; END IF; RETURN NEW; END $$;
CREATE TRIGGER app_write INSTEAD OF INSERT OR UPDATE ON padova.app_referral_payments FOR EACH ROW EXECUTE FUNCTION padova.app_write_referral_payments();
