 ELSIF TG_OP='UPDATE' THEN
 UPDATE padova."referral_terms" SET "booking_id"=NEW."booking_id","referrer_id"=NEW."referrer_id","basis"=CASE WHEN NEW.basis='fixed' THEN 'fixed' ELSE 'markup_profit' END,"percentage"=CASE WHEN NEW.basis='fixed' THEN NULL ELSE NEW.rate_bps::numeric/10000 END,"fixed_amount"=CASE WHEN NEW.basis='fixed' THEN NEW.fixed_amount::numeric/100 ELSE NULL END,"after_commission_receipt"=NEW."after_receipt","app_due_on"=NEW."due_on","app_command_id"=NEW."command_id","agreed_date"=NEW.due_on WHERE "id"=OLD."id";
 ELSE RAISE EXCEPTION 'Adapter deletion is not permitted'; END IF; RETURN NEW; END $$;
